  "common/rules.json": {
    "$schema": "https://json-schema.org/draft/2020-12/schema",
    "$id": "https://sduikit.dev/schemas/common/rules.json",
    "title": "Rules",
    "description": "When a widget may be shown. `audience` is a free-form map the host app defines; it matches when, for every key, the client has at least one of the listed values. `to` is exclusive.",
    "type": "object",
    "properties": {
      "countries": {
        "type": "array",
        "items": {
          "type": "string",
          "pattern": "^[A-Z]{2}$"
        },
        "minItems": 1,
        "uniqueItems": true
      },
      "audience": {
        "type": "object",
        "additionalProperties": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          },
          "minItems": 1
        }
      },
      "minAppVersion": {
        "type": "string",
        "pattern": "^\\d+\\.\\d+\\.\\d+$"
      },
      "from": {
        "type": "string",
        "format": "date-time"
      },
      "to": {
        "type": "string",
        "format": "date-time"
      }
    },
    "additionalProperties": false
  },
